package com.pousadamarealta;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import io.javalin.Javalin;
import io.javalin.testtools.JavalinTest;
import org.junit.jupiter.api.Test;

import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

class AppIT {

    @Test
    void shouldGetRooms() {
        JavalinTest.test((server, client) -> {
            var response = client.get("/rooms");
            assertThat(response.code()).isEqualTo(200);

            ObjectMapper mapper = new ObjectMapper();
            mapper.registerModule(new JavaTimeModule());
            var rooms = mapper.readValue(response.body().string(), Object[].class);
            assertThat(rooms).hasSize(5);
        });
    }

    @Test
    void shouldCreateReservation() {
        JavalinTest.test((server, client) -> {
            String requestBody = """
                {
                    "roomNumber": "101",
                    "guestName": "João Silva",
                    "guestEmail": "joao@example.com",
                    "guestCpf": "12345678901",
                    "checkIn": "2027-03-10",
                    "checkOut": "2027-03-12",
                    "guests": 2,
                    "ratePlan": "STANDARD"
                }
                """;

            var response = client.post("/reservations", requestBody);
            assertThat(response.code()).isEqualTo(201);

            ObjectMapper mapper = new ObjectMapper();
            mapper.registerModule(new JavaTimeModule());
            var reservation = mapper.readValue(response.body().string(), Map.class);
            assertThat(reservation.get("id")).isEqualTo(1);
            assertThat(reservation.get("status")).isEqualTo("PENDING");
        });
    }

    @Test
    void shouldReturnErrorWhenRoomNotFound() {
        JavalinTest.test((server, client) -> {
            String requestBody = """
                {
                    "roomNumber": "999",
                    "guestName": "João Silva",
                    "guestEmail": "joao@example.com",
                    "guestCpf": "12345678901",
                    "checkIn": "2027-03-10",
                    "checkOut": "2027-03-12",
                    "guests": 2,
                    "ratePlan": "STANDARD"
                }
                """;

            var response = client.post("/reservations", requestBody);
            assertThat(response.code()).isEqualTo(404);

            ObjectMapper mapper = new ObjectMapper();
            var error = mapper.readValue(response.body().string(), Map.class);
            assertThat(error.get("error")).isEqualTo("ROOM_NOT_FOUND");
        });
    }

    @Test
    void shouldReturnErrorWhenCapacityExceeded() {
        JavalinTest.test((server, client) -> {
            String requestBody = """
                {
                    "roomNumber": "101",
                    "guestName": "João Silva",
                    "guestEmail": "joao@example.com",
                    "guestCpf": "12345678901",
